<?php
/** Everyday cybersecurity: passwords and password managers, two-factor authentication, phishing and scams, devices, updates and backups. */

return [
    'id' => 'security-basics', 'family' => 'security', 'after' => null, 'categories' => ['security', 'productivity'],
    'title' => L('Sicurezza informatica di base', 'Cybersecurity Basics'), 'short' => L('Sicurezza base', 'Security Basics'), 'level' => L('Base', 'Basics'),
    'desc' => L('Proteggersi online ogni giorno: password e gestori di password, autenticazione a due fattori, phishing e truffe, aggiornamenti, backup e reti Wi-Fi.', 'Staying safe online every day: passwords and password managers, two-factor authentication, phishing and scams, updates, backups and Wi-Fi networks.'),
    'lessons' => [
        lesson('passwords', L('Password e gestori di password', 'Passwords and password managers'), [
            P('Una buona password è **lunga** e **unica**: lunga (almeno 14-16 caratteri, una frase di parole a caso va benissimo) e diversa per ogni servizio. Se un sito subisce un furto di dati, una password riutilizzata apre anche tutti gli altri tuoi account.', 'A good password is **long** and **unique**: long (at least 14-16 characters, a phrase of random words is great) and different for every service. If one site suffers a data breach, a reused password also opens all your other accounts.'),
            P('Nessuno ricorda cento password diverse: per questo esistono i **gestori di password**, che le generano casuali, le conservano cifrate dietro una sola password principale e le compilano da soli solo sul sito giusto (aiutando anche contro il phishing). Sempre più servizi supportano le **passkey**, che sostituiscono la password con il dispositivo e l’impronta o il volto.', 'Nobody remembers a hundred different passwords: that is why **password managers** exist, which generate random ones, store them encrypted behind a single master password and fill them in only on the right site (also helping against phishing). More and more services support **passkeys**, which replace the password with your device plus fingerprint or face.'),
        ], [
            Q('p1', L('Che cosa rende forte una password?', 'What makes a password strong?'), [L('Essere lunga e unica', 'Being long and unique'), L('Contenere il tuo nome', 'Containing your name'), L('Essere corta e facile', 'Being short and easy'), L('Essere uguale ovunque', 'Being the same everywhere')], 0, L('Lunghezza e unicità.', 'Length and uniqueness.')),
            Q('p2', L('Perché non riutilizzare le password?', 'Why not reuse passwords?'), [L('Un furto su un sito apre anche gli altri account', 'One breach opens your other accounts too'), L('Perché si consumano', 'Because they wear out'), L('Non c’è motivo', 'There is no reason'), L('Perché sono a pagamento', 'Because they cost money')], 0, L('Effetto domino.', 'Domino effect.')),
            Q('p3', L('Che cosa fa un gestore di password?', 'What does a password manager do?'), [L('Genera, conserva cifrate e compila le password', 'Generates, stores encrypted and fills passwords'), L('Pubblica le password', 'Publishes passwords'), L('Le stampa', 'Prints them'), L('Le cambia a caso ogni giorno', 'Changes them randomly daily')], 0, L('Una sola password da ricordare.', 'One password to remember.')),
        ], task('text', L('Scrivi tre regole per le tue password, una per riga con `-`, tra cui una sul **gestore di password**.', 'Write three rules for your passwords, one per line with `-`, including one about a **password manager**.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre regole', 'Three rules')), re('gestore|manager|password manager', L('Una sul gestore', 'One about the manager')), re('lung|long|unic|unique|divers|different|riutil|reuse', L('Lunghezza o unicità', 'Length or uniqueness'))], '', "- password lunghe, almeno 16 caratteri\n- una password diversa per ogni servizio\n- usare un gestore di password per generarle e ricordarle"), [
            dMatch(pMatch(), [[L('Password lunga', 'Long password'), L('Difficile da indovinare', 'Hard to guess')], [L('Password unica', 'Unique password'), L('Un furto non apre altri account', 'A breach opens no other accounts')], [L('Gestore di password', 'Password manager'), L('Genera e ricorda', 'Generates and remembers')], ['Passkey', L('Accesso senza password', 'Passwordless sign-in')]], L('Chiavi digitali.', 'Digital keys.')),
            dFlash(pFlash(), [[L('Una frase di parole a caso può essere una buona password', 'A phrase of random words can be a good password'), true], [L('Usare la stessa password ovunque è sicuro', 'Using the same password everywhere is safe'), false], [L('Un gestore di password compila solo sul sito giusto', 'A password manager fills only on the right site'), true], [L('La data di nascita è una password forte', 'Your birth date is a strong password'), false]], L('Password che proteggono.', 'Passwords that protect.')),
        ]),
        lesson('2fa', L('Autenticazione a due fattori', 'Two-factor authentication'), [
            P('Con l’**autenticazione a due fattori** (2FA) per entrare non basta la password: serve anche una seconda prova, come un codice da un’app di autenticazione, una chiave di sicurezza fisica o una passkey. Anche se qualcuno ruba la password, non riesce a entrare.', 'With **two-factor authentication** (2FA) a password is not enough to sign in: a second proof is needed too, such as a code from an authenticator app, a physical security key or a passkey. Even if someone steals the password, they cannot get in.'),
            P('In ordine di sicurezza: le **chiavi di sicurezza** e le passkey sono le più robuste, poi le **app di autenticazione**, poi gli SMS (meglio di niente, ma attaccabili con lo scambio di SIM). Attiva il 2FA prima di tutto su email, banca, social e gestore di password, e conserva i **codici di recupero** in un posto sicuro.', 'In order of security: **security keys** and passkeys are the strongest, then **authenticator apps**, then SMS (better than nothing, but vulnerable to SIM swapping). Turn on 2FA first on email, bank, social media and password manager, and keep the **recovery codes** somewhere safe.'),
            Tip('Nessuna banca o azienda seria ti chiederà mai al telefono o per messaggio il codice di verifica che hai ricevuto: chi lo chiede è un truffatore.', 'No serious bank or company will ever ask you by phone or message for the verification code you received: whoever asks is a scammer.'),
        ], [
            Q('f1', L('Che vantaggio dà il 2FA?', 'What does 2FA give you?'), [L('Una password rubata non basta per entrare', 'A stolen password is not enough to get in'), L('Non serve più la password', 'The password is no longer needed'), L('Internet più veloce', 'Faster internet'), L('Niente', 'Nothing')], 0, L('Serve una seconda prova.', 'A second proof is needed.')),
            Q('f2', L('Quale secondo fattore è il più debole?', 'Which second factor is weakest?'), ['SMS', L('Chiave di sicurezza', 'Security key'), L('App di autenticazione', 'Authenticator app'), 'Passkey'], 0, L('Attaccabile con lo scambio di SIM.', 'Vulnerable to SIM swapping.')),
            Q('f3', L('Qualcuno al telefono ti chiede il codice di verifica appena ricevuto. Che fai?', 'Someone on the phone asks for the verification code you just got. What do you do?'), [L('Non lo do e riattacco', 'Do not give it and hang up'), L('Glielo leggo', 'Read it out'), L('Glielo mando per SMS', 'Text it to them'), L('Lo pubblico', 'Post it')], 0, L('È sempre una truffa.', 'It is always a scam.')),
        ], task('text', L('Ordina dal più sicuro al meno sicuro, una riga per metodo numerata da `1.` a `3.`: SMS, chiave di sicurezza, app di autenticazione.', 'Order from most to least secure, one line per method numbered `1.` to `3.`: SMS, security key, authenticator app.'), '', [re('^1\.\s*(chiave|security key|key)', L('Prima la chiave', 'Key first')), re('^2\.\s*(app)', L('Poi l’app', 'Then the app')), re('^3\.\s*SMS', L('Infine gli SMS', 'Finally SMS'))], '', "1. chiave di sicurezza\n2. app di autenticazione\n3. SMS"), [
            dOrder(pSort(), [L('Chiave di sicurezza o passkey', 'Security key or passkey'), L('App di autenticazione', 'Authenticator app'), 'SMS', L('Solo password', 'Password only')], L('Dal più al meno sicuro.', 'From most to least secure.')),
            dFlash(pFlash(), [[L('Il 2FA va attivato prima sull’email', '2FA should be enabled on email first'), true], [L('Una banca può chiederti il codice al telefono', 'A bank may ask for your code by phone'), false], [L('I codici di recupero vanno conservati al sicuro', 'Recovery codes should be stored safely'), true], [L('Con il 2FA la password non conta più nulla', 'With 2FA the password no longer matters'), false]], L('Due chiavi sono meglio di una.', 'Two keys beat one.')),
        ]),
        lesson('phishing', L('Phishing e truffe', 'Phishing and scams'), [
            P('Il **phishing** è un messaggio falso (email, SMS, chat, telefonata) che si finge una banca, un corriere, un collega o un servizio noto per farti cliccare un link, scaricare un allegato o rivelare dati. Con l’AI i messaggi sono sempre più curati e anche le voci possono essere imitate.', '**Phishing** is a fake message (email, SMS, chat, phone call) pretending to be a bank, courier, colleague or known service to make you click a link, download an attachment or reveal data. With AI messages are increasingly polished and even voices can be imitated.'),
            C('Segnali d’allarme
• urgenza o minaccia: “il conto verrà bloccato entro 24 ore”
• mittente o indirizzo strano: poste-italiane-verifica.com
• richiesta di password, codici, dati della carta
• allegati inattesi (.zip, .exe, documenti con macro)
• offerte troppo belle, vincite, pacchi in attesa di pagamento', 'text'),
            P('La regola: **non usare i link e i numeri del messaggio**. Apri tu il sito o l’app ufficiale, o chiama il numero che conosci. Passa il mouse sui link per vedere l’indirizzo vero. Se hai cliccato o inserito dati, cambia subito la password e avvisa la banca o l’assistenza.', 'The rule: **do not use the links and numbers in the message**. Open the official site or app yourself, or call the number you know. Hover over links to see the real address. If you clicked or entered data, change the password at once and alert the bank or support.'),
        ], [
            Q('h1', L('Qual è un segnale tipico di phishing?', 'What is a typical phishing sign?'), [L('Urgenza e richiesta di dati', 'Urgency and a request for data'), L('Un messaggio di un amico che conosci, senza richieste', 'A message from a friend with no requests'), L('Una newsletter a cui sei iscritto', 'A newsletter you subscribed to'), L('Una fattura attesa dal portale ufficiale', 'An expected invoice from the official portal')], 0, L('Fretta = attenzione.', 'Hurry = caution.')),
            Q('h2', L('Ricevi un SMS dalla “banca” con un link. Che fai?', 'You get an SMS from the “bank” with a link. What do you do?'), [L('Apro io l’app ufficiale senza usare il link', 'Open the official app myself without the link'), L('Clicco subito', 'Click at once'), L('Rispondo con i miei dati', 'Reply with my data'), L('Inoltro a tutti', 'Forward to everyone')], 0, L('Mai i link del messaggio.', 'Never the message’s links.')),
            Q('h3', L('Che cosa fare se hai inserito la password su un sito falso?', 'What to do if you entered your password on a fake site?'), [L('Cambiarla subito e attivare il 2FA', 'Change it at once and enable 2FA'), L('Niente', 'Nothing'), L('Aspettare un mese', 'Wait a month'), L('Cancellare il browser', 'Delete the browser')], 0, L('Prima si agisce, meglio è.', 'The sooner the better.')),
        ], task('text', L('Leggi questo messaggio e scrivi tre segnali di phishing, uno per riga con `-`: “URGENTE: il tuo pacco è bloccato. Paga 1,99 € entro oggi su poste-consegne-it.com o verrà restituito.”', 'Read this message and write three phishing signs, one per line with `-`: “URGENT: your parcel is blocked. Pay €1.99 today at poste-consegne-it.com or it will be returned.”'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre segnali', 'Three signs')), re('urgen|fretta|oggi|today|hurry', L('L’urgenza', 'The urgency')), re('indirizz|dominio|sito|link|address|domain|url', L('L’indirizzo sospetto', 'The suspicious address')), re('pag|soldi|pay|money|€|carta|card', L('La richiesta di pagamento', 'The payment request'))], '', "- crea urgenza: “entro oggi”\n- il sito poste-consegne-it.com non è quello ufficiale\n- chiede un pagamento con la carta per un pacco"), [
            dMatch(pMatch(), [[L('Urgenza', 'Urgency'), L('Ti spinge a non pensare', 'Pushes you not to think')], [L('Dominio strano', 'Odd domain'), L('Sito falso', 'Fake site')], [L('Allegato inatteso', 'Unexpected attachment'), L('Possibile malware', 'Possible malware')], [L('Richiesta di codici', 'Code request'), L('Furto dell’account', 'Account theft')], [L('Sito ufficiale', 'Official site'), L('Aprilo tu, non dal link', 'Open it yourself, not from the link')]], L('Riconoscere le trappole.', 'Spotting the traps.')),
            dFlash(pFlash(), [[L('Con l’AI le voci si possono imitare', 'With AI voices can be imitated'), true], [L('Un messaggio senza errori è sicuramente vero', 'A message without typos is surely genuine'), false], [L('Passare il mouse su un link mostra l’indirizzo vero', 'Hovering a link shows the real address'), true], [L('Le banche chiedono la password per email', 'Banks ask for passwords by email'), false]], L('Fermarsi e verificare.', 'Stop and verify.')),
        ]),
        lesson('devices', L('Dispositivi, aggiornamenti e backup', 'Devices, updates and backups'), [
            P('Gli **aggiornamenti** di sistema, browser e app chiudono falle che i criminali conoscono e sfruttano: attiva gli aggiornamenti automatici. Blocca telefono e computer con un codice o la biometria, attiva la **cifratura** del disco e la funzione per localizzare e cancellare a distanza un dispositivo perso.', '**Updates** to the system, browser and apps close holes that criminals know and exploit: turn on automatic updates. Lock phone and computer with a code or biometrics, turn on disk **encryption** and the feature to locate and remotely wipe a lost device.'),
            P('I **backup** ti salvano da guasti, furti e ransomware (il malware che cifra i file e chiede un riscatto). La regola **3-2-1**: tre copie dei dati, su due supporti diversi, di cui una fuori casa (per esempio nel cloud). Sulle **reti Wi-Fi pubbliche** evita operazioni sensibili o usa una VPN affidabile.', '**Backups** save you from failures, theft and ransomware (malware that encrypts files and demands a ransom). The **3-2-1** rule: three copies of your data, on two different media, one of them off-site (for example in the cloud). On **public Wi-Fi** avoid sensitive operations or use a trustworthy VPN.'),
        ], [
            Q('d1', L('Perché installare gli aggiornamenti?', 'Why install updates?'), [L('Chiudono falle di sicurezza note', 'They close known security holes'), L('Per cambiare i colori', 'To change colours'), L('Rallentano il dispositivo', 'They slow the device'), L('Non servono', 'They are not needed')], 0, L('Meglio automatici.', 'Better automatic.')),
            Q('d2', L('Che cosa dice la regola 3-2-1 dei backup?', 'What does the 3-2-1 backup rule say?'), [L('Tre copie, due supporti, una fuori casa', 'Three copies, two media, one off-site'), L('Tre password, due email, un telefono', 'Three passwords, two emails, one phone'), L('Un backup ogni tre anni', 'One backup every three years'), L('Niente', 'Nothing')], 0, L('Contro guasti e ransomware.', 'Against failures and ransomware.')),
            Q('d3', L('Che cos’è il ransomware?', 'What is ransomware?'), [L('Malware che cifra i file e chiede un riscatto', 'Malware that encrypts files and demands ransom'), L('Un antivirus', 'An antivirus'), L('Un tipo di backup', 'A kind of backup'), L('Una rete Wi-Fi', 'A Wi-Fi network')], 0, L('Il backup è la difesa migliore.', 'Backup is the best defence.')),
        ], task('text', L('Scrivi una checklist di quattro azioni per mettere in sicurezza un telefono nuovo, una per riga con `[ ]`, tra cui gli **aggiornamenti** e il **backup**.', 'Write a checklist of four actions to secure a new phone, one per line with `[ ]`, including **updates** and **backup**.'), "[ ] \n[ ] \n[ ] \n[ ] ", [re('^\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S', L('Quattro azioni', 'Four actions')), re('aggiorn|update', L('Gli aggiornamenti', 'Updates')), re('backup|copia|backup', L('Il backup', 'Backup'))], '', "[ ] attivare gli aggiornamenti automatici\n[ ] codice di blocco e impronta\n[ ] attivare il backup nel cloud\n[ ] attivare la funzione trova e inizializza a distanza"), [
            dMatch(pMatch(), [[L('Aggiornamenti', 'Updates'), L('Chiudono le falle', 'Close holes')], [L('Cifratura', 'Encryption'), L('Dati illeggibili se rubato', 'Data unreadable if stolen')], ['3-2-1', L('Regola dei backup', 'Backup rule')], ['Ransomware', L('File cifrati per riscatto', 'Files encrypted for ransom')], ['VPN', L('Protezione su reti pubbliche', 'Protection on public networks')]], L('Dispositivi protetti.', 'Protected devices.')),
            dFlash(pFlash(), [[L('Un backup aiuta contro il ransomware', 'A backup helps against ransomware'), true], [L('Rimandare gli aggiornamenti per mesi è prudente', 'Postponing updates for months is prudent'), false], [L('Si può cancellare a distanza un telefono perso', 'A lost phone can be wiped remotely'), true], [L('Il Wi-Fi pubblico è sempre sicuro per la banca online', 'Public Wi-Fi is always safe for online banking'), false]], L('Prevenire è meglio.', 'Prevention is better.')),
        ]),
        lesson('networks', L('Wi-Fi, privacy e cosa fare dopo un attacco', 'Wi-Fi, privacy and what to do after an attack'), [
            P('Su una **Wi-Fi pubblica** usa siti in HTTPS e, se serve, una **VPN** affidabile; disattiva la condivisione dei file. A casa cambia la password del router, usa WPA2 o WPA3 e aggiorna il firmware.', 'On **public Wi-Fi** use HTTPS sites and, if needed, a trustworthy **VPN**; turn off file sharing. At home change the router password, use WPA2 or WPA3 and update the firmware.'),
            P('Se pensi di essere stato colpito (un account violato, un clic su un link sospetto): **cambia subito la password** da un dispositivo sicuro, attiva la 2FA, chiudi le sessioni aperte, avvisa banca o servizio coinvolto, e controlla se il tuo indirizzo compare in violazioni note (per esempio su Have I Been Pwned).', 'If you think you were hit (a hacked account, a click on a suspicious link): **change the password at once** from a safe device, turn on 2FA, sign out other sessions, warn the bank or service involved, and check whether your address appears in known breaches (for example on Have I Been Pwned).'),
        ], [
            Q('nw1', L('Che cosa aiuta su una Wi-Fi pubblica?', 'What helps on public Wi-Fi?'), [L('HTTPS e una VPN affidabile', 'HTTPS and a trustworthy VPN'), L('Condividere i file', 'Sharing files'), L('Disattivare gli aggiornamenti', 'Turning off updates'), L('Usare la stessa password', 'Using the same password')], 0, L('Il traffico resta cifrato.', 'Traffic stays encrypted.')),
            Q('nw2', L('Primo passo dopo un account violato?', 'First step after a hacked account?'), [L('Cambiare la password da un dispositivo sicuro', 'Change the password from a safe device'), L('Aspettare', 'Wait'), L('Cancellare il computer', 'Wipe the computer'), L('Rispondere all’attaccante', 'Reply to the attacker')], 0, L('Poi 2FA e sessioni.', 'Then 2FA and sessions.')),
            Q('nw3', L('Quale protezione Wi-Fi usare a casa?', 'Which Wi-Fi protection should you use at home?'), ['WPA2 o WPA3', 'WEP', L('Nessuna', 'None'), 'Bluetooth'], 0, L('WEP è superata.', 'WEP is obsolete.')),
        ], task('text', L('Scrivi tre azioni dopo un account violato, una per riga con `-`: password, 2FA, sessioni.', 'Write three actions after a hacked account, one per line with `-`: password, 2FA, sessions.'), '', [re('^-.*(password)', L('Cambi la password', 'You change the password')), re('^-.*(2FA|due fattori|two-factor)', L('Attivi la 2FA', 'You turn on 2FA')), re('^-.*(session|disconnett|esci|sign out|log out)', L('Chiudi le sessioni', 'You close sessions'))], '', "- Cambio subito la password da un dispositivo sicuro\n- Attivo la 2FA\n- Chiudo tutte le sessioni aperte"), [
            dOrder(pSort(), [L('Cambia la password', 'Change the password'), L('Attiva la 2FA', 'Turn on 2FA'), L('Chiudi le altre sessioni', 'Sign out other sessions'), L('Avvisa il servizio', 'Warn the service'), L('Controlla le violazioni note', 'Check known breaches')], L('Dopo un attacco.', 'After an attack.')),
            dFlash(pFlash(), [[L('WEP è una protezione superata', 'WEP is obsolete protection'), true], [L('Su Wi-Fi pubblica conviene condividere i file', 'On public Wi-Fi sharing files is wise'), false], [L('Il firmware del router va aggiornato', 'Router firmware should be updated'), true], [L('Dopo una violazione basta aspettare', 'After a breach waiting is enough'), false]], L('Reti e reazioni.', 'Networks and reactions.')),
        ]),
    ],
];
